// Derived combinational state output logic + one-hot encoded state
// flip-flop input (the same as the one-hot encoded state) gives the
// same transfer function as the explicit state transition function.
module TopModule (
  input  [5:0] y,
  input        w,
  output       Y1,
  output       Y3
);
  wire [5:0] ns;
  assign ns[0] = y[1];
