  assign ns[3] = (y[0]) ? 1'b0 : (y[1]) ? y[4] : 1'b0;
  assign ns[4] = (y[0]) ? 1'b1 : (y[1]) ? 1'b0 : y[5];
  assign ns[5] = (y[0]) ? y[2] : (y[1]) ? 1'b0 : 1'b1;
  assign Y1 = ns[1];
  assign Y3 = ns[3];
  reg [5:0] s;
  always @(posedge w) s <= ns;
  assign Y1 = s[1];
  assign Y3 = s[3];
endmodule

