// One-hot encoded finite-state machine, state output logic, and the state
// flip-flops inline, as a single inline nested module (the "TopModule"
// as per the problem description).
module TopModule (
    input  [5:0] y,
    input        w,
    output       Y1,
    output       Y3
);
    wire          ns0_0 = y[0];
    wire          ns0_1 = y[1];
    wire          ns1_0 = y[2];
    wire          ns1_1 = y[3];
    wire          ns2_0 = y[4];
    wire          ns2_1 = y[5];
    wire          ns3_0 = ns0_0 & w;
    wire          ns3_1 = ns0_1 & w;
    wire          ns4_0 = ns1_0 & w;
    wire          ns4_1 = ns1_1 & w;
    wire          ns5_0 = ns2_0 & w;
    wire          ns5_1 = ns2_1 & w;
    wire          ns6_0 = ns3_0 | (ns4_0 & ~w);
    wire          ns6_1 = ns3_1 | (ns4_1 & ~w);
    wire          ns7_0 = ns5_0 & w;
    wire          ns7_1 = ns5_1 & w;
    wire          ns8_0 = ns6_0 | (ns7_0 & ~w);
    wire          ns8_1 = ns6_1 | (ns7_1 & ~w);
    assign Y1 = ns0_1;
    assign Y3 = ns2_1;
endmodule

